from pathlib import Path
import csv,json
B=Path(__file__).parent
F='paper_id title authors year venue doi_or_arxiv official_url version source_verified full_text_access discussion_access domain axis_tags original_rq dataset stimulus brain_measurement model_method training_objective main_findings scientific_contribution limitations future_directions future_direction_source_location transfer_idea relevant_datasets novelty_risk evidence_level agent verification_date source needs_followup'.split()
assert len(F)==32
rows=[]
def add(id,title,authors,year,venue,doi,src,**kw):
 meta=json.loads((B/'evidence'/f'{src}.json').read_text())
 r=dict.fromkeys(F,'미확인 또는 해당 없음')
 r.update(paper_id=id,title=title,authors=authors,year=year,venue=venue,doi_or_arxiv=doi,official_url=meta['url'],version='2026-11-12 공식 저장소 응답 스냅샷; SHA256은 evidence 메타데이터 참조',source_verified='검증됨: 저자/공식 연구실 문서; 서지 신뢰 높음',full_text_access='논문 원문 미열람; 공식 코드/데이터 문서 직접 확인',discussion_access='아니오',domain='정서신경과학',axis_tags='A;E;F;Q;S;X',future_directions='저자 Discussion 미확인; 직접 제안으로 귀속하지 않음',future_direction_source_location='없음',relevant_datasets='Horikawa 우선; 다른 자료는 별도 감사 필요',novelty_risk='기존 분류/회귀의 모델 교체만으로 신규성 없음',evidence_level='E1',agent='02_affective_neuroscience',verification_date='2026-11-12',source=f'evidence/{src}.source; evidence/{src}.json',needs_followup='원문 및 데이터 세부 구조 추가 확인')
 r.update(kw); rows.append(r)
